-- Consolidated CRM schema bundle for Platform's "create a tenant's dedicated
-- database" feature (TenantMigrationController -> ProvisioningService).
--
-- Generated by concatenating knightage-crm's own PLAIN (non-.production.sql)
-- sql/0*.sql migrations, in numeric order -- deliberately NOT the
-- appuser.-qualified .production.sql twins. Reasoning: the login that creates
-- a fresh database becomes its owner (dbo) by default, so unqualified
-- CREATE TABLE/PROCEDURE statements land in dbo consistently -- exactly what
-- CRM's own repository code expects, since it always calls procs/tables
-- unqualified (e.g. "usp_Leads_GetFieldSales", not "appuser.usp_..."). Mixing
-- in appuser.-qualified statements caused "Cannot find the object
-- 'appuser.Documents'" on a fresh database, since nothing there maps appuser
-- to a same-named schema the way the real (much older) Knightage_Crm
-- database happens to.
--
-- A hard GO is inserted after EVERY file, regardless of whether that file's
-- own last line already had one -- not every migration ends with a trailing
-- GO (e.g. 039_lead_geo_location.sql doesn't), which is harmless standalone
-- but merges into the NEXT file's leading CREATE PROCEDURE otherwise ("must
-- be the first statement in a batch").
--
-- MAINTENANCE: regenerate this file whenever knightage-crm's schema changes
-- (a new sql/0NN_*.sql migration lands). See README.md in this folder.

-- ===== 001_init.sql =====
-- Bootstrap schema for local/dev use.
-- Once knightage-platform's migration orchestration exists, this becomes the
-- versioned source it applies instead of being run by hand.

CREATE TABLE PipelineStages (
    Id UNIQUEIDENTIFIER PRIMARY KEY,
    Name NVARCHAR(100) NOT NULL,
    SortOrder INT NOT NULL,
    IsActive BIT NOT NULL DEFAULT 1
);

CREATE TABLE Leads (
    Id UNIQUEIDENTIFIER PRIMARY KEY,
    Name NVARCHAR(200) NOT NULL,
    Email NVARCHAR(320) NULL,
    Phone NVARCHAR(50) NULL,
    Company NVARCHAR(200) NULL,
    PipelineStageId UNIQUEIDENTIFIER NOT NULL REFERENCES PipelineStages(Id),
    Notes NVARCHAR(1000) NULL,
    Source NVARCHAR(50) NOT NULL DEFAULT 'Manual',
    CreatedAtUtc DATETIME2 NOT NULL
);


GO

-- ===== 002_lead_activities.sql =====
-- Adds the activity timeline for a lead: notes today, the same table can carry
-- future activity types (call logs, emails, task completions, stage-change
-- entries) once those slices land, without a new table per type.

CREATE TABLE LeadActivities (
    Id UNIQUEIDENTIFIER PRIMARY KEY,
    LeadId UNIQUEIDENTIFIER NOT NULL REFERENCES Leads(Id),
    Type NVARCHAR(50) NOT NULL DEFAULT 'Note',
    Content NVARCHAR(2000) NOT NULL,
    CreatedByUserId NVARCHAR(100) NULL,
    CreatedAtUtc DATETIME2 NOT NULL
);

CREATE INDEX IX_LeadActivities_LeadId ON LeadActivities(LeadId);


GO

-- ===== 003_lead_activity_metadata.sql =====
-- Adds structured metadata to activity entries (e.g. stage-change from/to names),
-- needed now that activities are auto-logged by the server, not just typed by a
-- user. Free text (Content) alone can't carry structured fields cleanly.

ALTER TABLE LeadActivities ADD Metadata NVARCHAR(MAX) NULL;


GO

-- ===== 004_tasks.sql =====
-- Follow-up tasks linked to a lead (User Stories Slice 1, Part B).

CREATE TABLE Tasks (
    Id UNIQUEIDENTIFIER PRIMARY KEY,
    LeadId UNIQUEIDENTIFIER NOT NULL REFERENCES Leads(Id),
    Title NVARCHAR(200) NOT NULL,
    Description NVARCHAR(2000) NULL,
    DueDate DATE NOT NULL,
    Status NVARCHAR(20) NOT NULL DEFAULT 'Open',
    AssignedToUserId NVARCHAR(100) NOT NULL,
    CreatedByUserId NVARCHAR(100) NULL,
    CreatedAtUtc DATETIME2 NOT NULL,
    CompletedAtUtc DATETIME2 NULL
);

CREATE INDEX IX_Tasks_LeadId ON Tasks(LeadId);
CREATE INDEX IX_Tasks_AssignedToUserId_Status ON Tasks(AssignedToUserId, Status);


GO

-- ===== 005_pipeline_stage_won_lost.sql =====
-- Lets an org mark which pipeline stage(s) count as "won" or "lost" for dashboard
-- reporting (User Stories Slice 1, Part C / C2), instead of matching stage names.

ALTER TABLE PipelineStages ADD IsWon BIT NOT NULL DEFAULT 0;
ALTER TABLE PipelineStages ADD IsLost BIT NOT NULL DEFAULT 0;


GO

-- ===== 006_performance_indexes.sql =====
-- The dashboard's pipeline-summary query runs a correlated COUNT(*) subquery against Leads
-- per pipeline stage; without an index on the join/filter column that's a full table scan of
-- Leads once per stage. Likewise LeadActivities.CreatedAtUtc (activity-summary's date filter)
-- and Tasks(Status, DueDate) (overdue-tasks' filter) had no supporting index -- the existing
-- Tasks index leads with AssignedToUserId, which doesn't help a query that filters on
-- Status/DueDate without it.
CREATE INDEX IX_Leads_PipelineStageId ON Leads(PipelineStageId);
CREATE INDEX IX_LeadActivities_CreatedAtUtc ON LeadActivities(CreatedAtUtc);
CREATE INDEX IX_Tasks_Status_DueDate ON Tasks(Status, DueDate);


GO

-- ===== 007_task_reminders.sql =====
-- Tracks whether a "due tomorrow" digest email has already been sent for a task,
-- so the reminder check (run opportunistically from TenantResolutionMiddleware,
-- see ITaskReminderDigestService) never double-sends.
ALTER TABLE Tasks ADD ReminderSentAtUtc DATETIME2 NULL;


GO

-- ===== 008_audit_fields.sql =====
-- Tracks who created/last modified a Lead, and who last modified a Task.
-- Tasks.CreatedByUserId and LeadActivities.CreatedByUserId already exist --
-- this fills the remaining gaps: Leads had no creator/modifier tracking at
-- all, and Tasks had no modifier tracking (only creator).

ALTER TABLE Leads ADD CreatedByUserId NVARCHAR(100) NULL;
ALTER TABLE Leads ADD UpdatedByUserId NVARCHAR(100) NULL;
ALTER TABLE Leads ADD UpdatedAtUtc DATETIME2 NULL;

ALTER TABLE Tasks ADD UpdatedByUserId NVARCHAR(100) NULL;
ALTER TABLE Tasks ADD UpdatedAtUtc DATETIME2 NULL;


GO

-- ===== 009_leads_created_at_index.sql =====
-- The leads list is paginated with ORDER BY CreatedAtUtc DESC / OFFSET-FETCH
-- (LeadRepository.GetPagedAsync), but 006_performance_indexes.sql only added
-- indexes for PipelineStageId, LeadActivities.CreatedAtUtc, and Tasks --
-- missing the one column the default leads list sort actually depends on.
-- Without it, every page of the leads list is a full table scan + sort.

CREATE INDEX IX_Leads_CreatedAtUtc ON Leads(CreatedAtUtc DESC);


GO

-- ===== 010_organization_id.sql =====
-- Multi-tenancy: adds OrganizationId to every table so one shared CRM database can
-- serve all tenants, replacing the one-database-per-tenant scheme. Per-tenant
-- databases required CREATE DATABASE rights that prod's appuser login doesn't have
-- (and shouldn't need) -- knightage-identity already proves the shared-table pattern
-- works (Organizations/Users scoped by a plain OrganizationId column).
--
-- Safe to add these as plain NOT NULL columns only because this migration is applied
-- to a freshly created, still-empty Knightage_Crm database (see sql/onetime for the
-- one-time cutover that copies the existing tenant's data in afterward). Never run
-- this against a database that already has rows without adding a DEFAULT and a
-- backfill step first.

ALTER TABLE PipelineStages ADD OrganizationId UNIQUEIDENTIFIER NOT NULL;
ALTER TABLE Leads ADD OrganizationId UNIQUEIDENTIFIER NOT NULL;
ALTER TABLE LeadActivities ADD OrganizationId UNIQUEIDENTIFIER NOT NULL;
ALTER TABLE Tasks ADD OrganizationId UNIQUEIDENTIFIER NOT NULL;

-- Existing indexes are dropped and replaced with OrganizationId leading, since it's
-- now the first filter in nearly every query -- SQL Server has no ALTER INDEX ...
-- ADD COLUMN, so narrower indexes are dropped outright rather than kept alongside a
-- new composite one. This isn't just an optimization: without an OrganizationId-
-- leading index, a query like "all tasks across the team" would scan every tenant's
-- rows, not just the caller's, once these tables are shared.

DROP INDEX IX_Leads_PipelineStageId ON Leads;
DROP INDEX IX_Leads_CreatedAtUtc ON Leads;
DROP INDEX IX_Tasks_AssignedToUserId_Status ON Tasks;
DROP INDEX IX_Tasks_Status_DueDate ON Tasks;
DROP INDEX IX_LeadActivities_LeadId ON LeadActivities;
DROP INDEX IX_LeadActivities_CreatedAtUtc ON LeadActivities;

CREATE INDEX IX_Leads_OrganizationId_PipelineStageId ON Leads(OrganizationId, PipelineStageId);
CREATE INDEX IX_Leads_OrganizationId_CreatedAtUtc ON Leads(OrganizationId, CreatedAtUtc DESC);
CREATE INDEX IX_Tasks_OrganizationId_AssignedToUserId_Status ON Tasks(OrganizationId, AssignedToUserId, Status);
CREATE INDEX IX_Tasks_OrganizationId_Status_DueDate ON Tasks(OrganizationId, Status, DueDate);
CREATE INDEX IX_LeadActivities_OrganizationId_LeadId ON LeadActivities(OrganizationId, LeadId);
CREATE INDEX IX_LeadActivities_OrganizationId_CreatedAtUtc ON LeadActivities(OrganizationId, CreatedAtUtc);

-- New: PipelineStages had no index beyond its PK before. GetActiveAsync's
-- WHERE IsActive=1 ORDER BY SortOrder would otherwise scan every tenant's stages.
CREATE INDEX IX_PipelineStages_OrganizationId_IsActive ON PipelineStages(OrganizationId, IsActive, SortOrder);

-- IX_Tasks_LeadId (from 004_tasks.sql) is deliberately left as-is, not made
-- composite: a single Lead's tasks already belong to exactly one org, so LeadId
-- alone stays highly selective regardless of how many tenants share the table.


GO

-- ===== 011_message_templates.sql =====
-- WhatsApp message templates for the Leads screen: org-wide, managed by
-- Owner/Admin (see MessageTemplatesController), usable by any authenticated
-- user when composing a WhatsApp message to a lead. Soft-deactivate only,
-- matching Team's IsActive-toggle pattern -- no hard delete anywhere in
-- this codebase's CRUD screens.

CREATE TABLE MessageTemplates (
    Id UNIQUEIDENTIFIER PRIMARY KEY,
    OrganizationId UNIQUEIDENTIFIER NOT NULL,
    Name NVARCHAR(150) NOT NULL,
    Body NVARCHAR(1000) NOT NULL,
    IsActive BIT NOT NULL DEFAULT 1,
    CreatedByUserId NVARCHAR(100) NULL,
    CreatedAtUtc DATETIME2 NOT NULL,
    UpdatedByUserId NVARCHAR(100) NULL,
    UpdatedAtUtc DATETIME2 NULL
);

CREATE INDEX IX_MessageTemplates_OrganizationId_IsActive ON MessageTemplates(OrganizationId, IsActive, Name);


GO

-- ===== 012_products.sql =====
-- Products catalog: org-wide, managed by Owner/Admin (see ProductsController),
-- optionally linkable to a Lead. Soft-deactivate only, matching MessageTemplates'
-- IsActive-toggle pattern -- no hard delete anywhere in this codebase's CRUD screens.

CREATE TABLE Products (
    Id UNIQUEIDENTIFIER PRIMARY KEY,
    OrganizationId UNIQUEIDENTIFIER NOT NULL,
    Name NVARCHAR(200) NOT NULL,
    Description NVARCHAR(1000) NULL,
    IsActive BIT NOT NULL DEFAULT 1,
    CreatedByUserId NVARCHAR(100) NULL,
    CreatedAtUtc DATETIME2 NOT NULL,
    UpdatedByUserId NVARCHAR(100) NULL,
    UpdatedAtUtc DATETIME2 NULL
);

CREATE INDEX IX_Products_OrganizationId_IsActive ON Products(OrganizationId, IsActive, Name);


GO

-- ===== 013_leads_product_owner.sql =====
-- Must run after 012_products.sql -- ProductId references Products(Id).
-- Optional Product link on a Lead, plus a Lead Owner (assignable, defaults to the
-- creator at the API layer -- see LeadsController.Create). Both nullable at the DB
-- level: Product is genuinely optional, and Owner is best-effort-backfilled below
-- rather than forced NOT NULL, so ancient rows with no CreatedByUserId don't block
-- the migration.

ALTER TABLE Leads ADD ProductId UNIQUEIDENTIFIER NULL REFERENCES Products(Id);
ALTER TABLE Leads ADD OwnerUserId NVARCHAR(100) NULL;
GO

-- New batch: a column added by ALTER TABLE above isn't visible to statements
-- compiled in the same batch, so this needs its own GO.
UPDATE Leads SET OwnerUserId = CreatedByUserId WHERE OwnerUserId IS NULL AND CreatedByUserId IS NOT NULL;

CREATE INDEX IX_Leads_OrganizationId_ProductId ON Leads(OrganizationId, ProductId);
CREATE INDEX IX_Leads_OrganizationId_OwnerUserId ON Leads(OrganizationId, OwnerUserId);


GO

-- ===== 014_meetings.sql =====
-- OrganizationId baked in from creation (this table postdates multi-tenancy, so it
-- doesn't need the older create-then-ALTER-later two-step Leads/Tasks went through --
-- matches 012_products.sql's pattern instead).
--
-- GoogleSyncStatus is kept separate from "GoogleEventId IS NULL" because null alone
-- can't distinguish "owner never connected Calendar" from "owner connected, but this
-- specific push failed" -- the UI needs to tell those two apart.

CREATE TABLE Meetings (
    Id UNIQUEIDENTIFIER PRIMARY KEY,
    OrganizationId UNIQUEIDENTIFIER NOT NULL,
    LeadId UNIQUEIDENTIFIER NOT NULL REFERENCES Leads(Id),
    Title NVARCHAR(200) NOT NULL,
    Description NVARCHAR(2000) NULL,
    StartAtUtc DATETIME2 NOT NULL,
    EndAtUtc DATETIME2 NOT NULL,
    Location NVARCHAR(500) NULL,
    Status NVARCHAR(20) NOT NULL DEFAULT 'Scheduled',          -- Scheduled | Cancelled | Completed
    OwnerUserId NVARCHAR(100) NOT NULL,                         -- whose Google Calendar this syncs to
    GoogleEventId NVARCHAR(1024) NULL,
    GoogleSyncStatus NVARCHAR(20) NOT NULL DEFAULT 'NotSynced', -- NotSynced | Synced | Failed | ReauthRequired
    GoogleSyncErrorAtUtc DATETIME2 NULL,
    CreatedByUserId NVARCHAR(100) NULL,
    CreatedAtUtc DATETIME2 NOT NULL,
    UpdatedByUserId NVARCHAR(100) NULL,
    UpdatedAtUtc DATETIME2 NULL,
    CancelledAtUtc DATETIME2 NULL
);

CREATE INDEX IX_Meetings_OrganizationId_LeadId ON Meetings(OrganizationId, LeadId);
CREATE INDEX IX_Meetings_OrganizationId_OwnerUserId_StartAtUtc ON Meetings(OrganizationId, OwnerUserId, StartAtUtc);


GO

-- ===== 015_product_price.sql =====
-- Additive: defaults existing rows to 0 so this can never fail against
-- existing Products. Required going forward at the UI/API layer, not via a
-- DB-level constraint (a 0 price is a legitimate value, e.g. a free item).

ALTER TABLE Products ADD Price DECIMAL(18,2) NOT NULL DEFAULT 0;


GO

-- ===== 016_lead_products.sql =====
-- Org-scoped from creation (postdates multi-tenancy, matches 012_products.sql /
-- 014_meetings.sql's pattern rather than the older ALTER-later two-step Leads/Tasks
-- went through).
--
-- UnitPrice is a snapshot of Product.Price at the moment the line item was added --
-- it does not update if the catalog price changes later, so a lead's recorded cost
-- never silently drifts. Duplicate (LeadId, ProductId) rows are allowed on purpose
-- (e.g. quoted 2 units in March, 1 more in June at a different price) -- same product
-- can appear on a lead more than once, same as a real quote/invoice.
--
-- Deliberately NOT backfilled from Leads.ProductId here -- see
-- sql/onetime/002_backfill_lead_products_from_leads.sql, run separately once real
-- prices exist on Products (Price doesn't exist until 015_product_price.sql, so an
-- immediate backfill would permanently snapshot UnitPrice = 0 for every existing lead).
--
-- Leads.ProductId itself is left untouched by this migration -- the app stops
-- reading/writing it, but the column/FK/index stay in place as an inert safety net.

CREATE TABLE LeadProducts (
    Id UNIQUEIDENTIFIER PRIMARY KEY,
    OrganizationId UNIQUEIDENTIFIER NOT NULL,
    LeadId UNIQUEIDENTIFIER NOT NULL REFERENCES Leads(Id),
    ProductId UNIQUEIDENTIFIER NOT NULL REFERENCES Products(Id),
    Quantity INT NOT NULL DEFAULT 1,
    UnitPrice DECIMAL(18,2) NOT NULL,
    CreatedAtUtc DATETIME2 NOT NULL
);

CREATE INDEX IX_LeadProducts_OrganizationId_LeadId ON LeadProducts(OrganizationId, LeadId);
CREATE INDEX IX_LeadProducts_OrganizationId_ProductId ON LeadProducts(OrganizationId, ProductId);


GO

-- ===== 017_meeting_reminders.sql =====
-- Tracks whether a "starting soon" digest email has already been sent for a meeting,
-- so the reminder check (run opportunistically from TenantResolutionMiddleware, see
-- IReminderDigestService) never double-sends. Mirrors 007_task_reminders.sql.
ALTER TABLE Meetings ADD ReminderSentAtUtc DATETIME2 NULL;


GO

-- ===== 018_lead_product_status.sql =====
-- Product-level status for a LeadProduct line item -- a fixed three-state set
-- (Active/Won/Lost), independent of the lead's own pipeline stage; not a reuse
-- of the org's customizable PipelineStages. StatusChangedAtUtc powers "stuck"
-- detection (see sibling migration 019_lead_pipeline_stage_changed_at.sql for
-- the Leads side) -- CreatedAtUtc can't be reused for that since it never
-- changes after insert, and a Quantity edit (LeadProductRepository.
-- UpdateQuantityAsync) must NOT reset this clock, so it's a dedicated column.

ALTER TABLE LeadProducts ADD Status NVARCHAR(20) NOT NULL DEFAULT 'Active';
ALTER TABLE LeadProducts ADD StatusChangedAtUtc DATETIME2 NULL;
GO

-- Backfill: every existing line item has implicitly been "Active" since
-- creation -- there's no real prior status-change instant, so CreatedAtUtc is
-- the honest starting point.
UPDATE LeadProducts SET StatusChangedAtUtc = CreatedAtUtc WHERE StatusChangedAtUtc IS NULL;


GO

-- ===== 019_lead_pipeline_stage_changed_at.sql =====
-- Dedicated stage-changed timestamp for Leads -- Lead.UpdatedAtUtc is generic
-- and gets clobbered by ANY field edit (LeadsController.Update sets it
-- unconditionally on every save), so it cannot be used to detect "stuck in
-- this stage too long." This column is only ever touched inside
-- LeadsController.Update's `if (previousStageId != request.PipelineStageId)`
-- branch, plus on Create/Import.

ALTER TABLE Leads ADD PipelineStageChangedAtUtc DATETIME2 NULL;
GO

-- Backfill: treat every existing lead as having entered its current stage at
-- creation -- there's no historical record of earlier stage changes before
-- this column existed.
UPDATE Leads SET PipelineStageChangedAtUtc = CreatedAtUtc WHERE PipelineStageChangedAtUtc IS NULL;


GO

-- ===== 020_documents.sql =====
-- Quotations and invoices generated from a lead's current products. A single
-- Documents table with a Type discriminator ('Quotation'/'Invoice') mirrors the
-- existing LeadActivity.Type convention, rather than two near-identical tables.
CREATE TABLE Documents (
    Id UNIQUEIDENTIFIER PRIMARY KEY,
    OrganizationId UNIQUEIDENTIFIER NOT NULL,
    LeadId UNIQUEIDENTIFIER NOT NULL REFERENCES Leads(Id),
    Type NVARCHAR(20) NOT NULL,                    -- 'Quotation' | 'Invoice'
    Number NVARCHAR(20) NOT NULL,                  -- 'QUO-0001' / 'INV-0001'
    Status NVARCHAR(20) NOT NULL DEFAULT 'Draft',  -- Draft -> Sent -> (Paid, Invoice only)
    TaxRatePercent DECIMAL(5,2) NOT NULL DEFAULT 0,
    Subtotal DECIMAL(18,2) NOT NULL,
    TaxAmount DECIMAL(18,2) NOT NULL,
    Total DECIMAL(18,2) NOT NULL,
    CreatedByUserId NVARCHAR(100) NULL,
    CreatedAtUtc DATETIME2 NOT NULL,
    SentAtUtc DATETIME2 NULL,
    PaidAtUtc DATETIME2 NULL
);
CREATE INDEX IX_Documents_OrganizationId_LeadId ON Documents(OrganizationId, LeadId);
CREATE INDEX IX_Documents_OrganizationId_Type ON Documents(OrganizationId, Type);
GO

-- Snapshot of the lead's LeadProducts at generation time -- deliberately
-- duplicated data, not a live join, so a document already sent to a customer
-- never silently changes if LeadProducts are edited/removed afterward.
CREATE TABLE DocumentLineItems (
    Id UNIQUEIDENTIFIER PRIMARY KEY,
    OrganizationId UNIQUEIDENTIFIER NOT NULL,
    DocumentId UNIQUEIDENTIFIER NOT NULL REFERENCES Documents(Id),
    ProductName NVARCHAR(200) NOT NULL,
    Quantity INT NOT NULL,
    UnitPrice DECIMAL(18,2) NOT NULL,
    LineTotal DECIMAL(18,2) NOT NULL
);
CREATE INDEX IX_DocumentLineItems_OrganizationId_DocumentId ON DocumentLineItems(OrganizationId, DocumentId);
GO


GO

-- ===== 021_product_stages.sql =====
-- Customizable per-org stages for LeadProduct, mirroring PipelineStages exactly --
-- replaces the old hardcoded Active/Won/Lost string with a real stage entity.
CREATE TABLE ProductStages (
    Id UNIQUEIDENTIFIER PRIMARY KEY,
    OrganizationId UNIQUEIDENTIFIER NOT NULL,
    Name NVARCHAR(100) NOT NULL,
    SortOrder INT NOT NULL,
    IsActive BIT NOT NULL DEFAULT 1,
    IsWon BIT NOT NULL DEFAULT 0,
    IsLost BIT NOT NULL DEFAULT 0
);
CREATE INDEX IX_ProductStages_OrganizationId_IsActive ON ProductStages(OrganizationId, IsActive, SortOrder);
GO

-- One-time backfill only, NOT a general new-org seed mechanism (PipelineStages
-- itself is never auto-seeded either -- a brand new org starts empty and uses the
-- inline "+ Add new stage" quick-add). Every org that already has LeadProducts
-- rows gets the same three stages their old Status strings represented, so
-- existing data has somewhere valid to point before ProductStageId goes NOT NULL.
INSERT INTO ProductStages (Id, OrganizationId, Name, SortOrder, IsActive, IsWon, IsLost)
SELECT NEWID(), OrganizationId, 'Active', 1, 1, 0, 0 FROM (SELECT DISTINCT OrganizationId FROM LeadProducts) o;
INSERT INTO ProductStages (Id, OrganizationId, Name, SortOrder, IsActive, IsWon, IsLost)
SELECT NEWID(), OrganizationId, 'Won', 2, 1, 1, 0 FROM (SELECT DISTINCT OrganizationId FROM LeadProducts) o;
INSERT INTO ProductStages (Id, OrganizationId, Name, SortOrder, IsActive, IsWon, IsLost)
SELECT NEWID(), OrganizationId, 'Lost', 3, 1, 0, 1 FROM (SELECT DISTINCT OrganizationId FROM LeadProducts) o;
GO

ALTER TABLE LeadProducts ADD ProductStageId UNIQUEIDENTIFIER NULL;
GO
UPDATE lp SET lp.ProductStageId = ps.Id
FROM LeadProducts lp
JOIN ProductStages ps ON ps.OrganizationId = lp.OrganizationId AND ps.Name = lp.Status;
GO

-- Verify zero rows before running the rest of this file (both locally and in
-- production): SELECT COUNT(*) FROM LeadProducts WHERE ProductStageId IS NULL;
ALTER TABLE LeadProducts ALTER COLUMN ProductStageId UNIQUEIDENTIFIER NOT NULL;
GO
ALTER TABLE LeadProducts ADD CONSTRAINT FK_LeadProducts_ProductStages FOREIGN KEY (ProductStageId) REFERENCES ProductStages(Id);
GO

-- Status (migration 018) has an unnamed DEFAULT 'Active' constraint, whose
-- auto-generated name differs per database -- must be dropped by lookup before
-- the column itself can be dropped.
DECLARE @statusDefaultConstraint NVARCHAR(200);
SELECT @statusDefaultConstraint = dc.name
FROM sys.default_constraints dc
JOIN sys.columns c ON c.default_object_id = dc.object_id
WHERE dc.parent_object_id = OBJECT_ID('LeadProducts') AND c.name = 'Status';
IF @statusDefaultConstraint IS NOT NULL
    EXEC('ALTER TABLE LeadProducts DROP CONSTRAINT ' + @statusDefaultConstraint);
GO
ALTER TABLE LeadProducts DROP COLUMN Status;
GO



GO

