CREATE PROCEDURE usp_Leads_GetNamesByIds
    @OrganizationId UNIQUEIDENTIFIER,
    @Ids NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT l.Id, l.Name
