-- ===== 036_stored_procs_dashboard_reports.sql =====
CREATE PROCEDURE usp_Dashboard_GetPipelineSummary
    @OrganizationId UNIQUEIDENTIFIER
AS
BEGIN
    SET NOCOUNT ON;
    SELECT ps.Id AS StageId, ps.Name AS StageName, ps.SortOrder,
           (SELECT COUNT(*) FROM Leads l WITH (NOLOCK) WHERE l.PipelineStageId = ps.Id AND l.OrganizationId = @OrganizationId AND l.IsActive = 1) AS LeadCount,
           (SELECT COALESCE(SUM(lp.Quantity * lp.UnitPrice), 0)
            FROM Leads l WITH (NOLOCK) JOIN LeadProducts lp WITH (NOLOCK) ON lp.LeadId = l.Id AND lp.OrganizationId = @OrganizationId
            WHERE l.PipelineStageId = ps.Id AND l.OrganizationId = @OrganizationId AND l.IsActive = 1) AS LeadValue
    FROM PipelineStages ps WITH (NOLOCK)
    WHERE ps.OrganizationId = @OrganizationId AND ps.IsActive = 1
    ORDER BY ps.SortOrder;
END
GO

CREATE PROCEDURE usp_Dashboard_GetWonLostCounts
    @OrganizationId UNIQUEIDENTIFIER,
    @Since DATETIME2 = NULL,
    @Until DATETIME2 = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        (SELECT COUNT(*) FROM Leads l WITH (NOLOCK) JOIN PipelineStages ps WITH (NOLOCK) ON ps.Id = l.PipelineStageId
         WHERE l.OrganizationId = @OrganizationId AND l.IsActive = 1 AND ps.IsWon = 1 AND (@Since IS NULL OR l.CreatedAtUtc >= @Since)
           AND (@Until IS NULL OR l.CreatedAtUtc < @Until)) AS Won,
        (SELECT COUNT(*) FROM Leads l WITH (NOLOCK) JOIN PipelineStages ps WITH (NOLOCK) ON ps.Id = l.PipelineStageId
         WHERE l.OrganizationId = @OrganizationId AND l.IsActive = 1 AND ps.IsLost = 1 AND (@Since IS NULL OR l.CreatedAtUtc >= @Since)
           AND (@Until IS NULL OR l.CreatedAtUtc < @Until)) AS Lost;
END
GO

CREATE PROCEDURE usp_Dashboard_GetActivityCountSince
    @OrganizationId UNIQUEIDENTIFIER,
    @Since DATETIME2
AS
BEGIN
    SET NOCOUNT ON;
    SELECT COUNT(*) FROM LeadActivities WITH (NOLOCK) WHERE OrganizationId = @OrganizationId AND CreatedAtUtc >= @Since;
END
