    SET NOCOUNT ON;
    SELECT COUNT(*) FROM Tasks WITH (NOLOCK) WHERE OrganizationId = @OrganizationId AND Status = 'Open' AND DueDate < @Today;
END
GO

CREATE PROCEDURE usp_Dashboard_GetStuckLeadsCount
    @OrganizationId UNIQUEIDENTIFIER,
    @Cutoff DATETIME2
AS
BEGIN
    SET NOCOUNT ON;
    SELECT COUNT(*) FROM (
        SELECT l.Id FROM Leads l WITH (NOLOCK)
        JOIN PipelineStages ps WITH (NOLOCK) ON ps.Id = l.PipelineStageId
        WHERE l.OrganizationId = @OrganizationId AND l.IsActive = 1
          AND ps.IsWon = 0 AND ps.IsLost = 0
          AND COALESCE(l.PipelineStageChangedAtUtc, l.CreatedAtUtc) < @Cutoff
        UNION
        SELECT lp.LeadId FROM LeadProducts lp WITH (NOLOCK)
        JOIN ProductStages pst WITH (NOLOCK) ON pst.Id = lp.ProductStageId AND pst.OrganizationId = @OrganizationId
        WHERE lp.OrganizationId = @OrganizationId
          AND pst.IsWon = 0 AND pst.IsLost = 0
          AND COALESCE(lp.StatusChangedAtUtc, lp.CreatedAtUtc) < @Cutoff
          AND EXISTS (SELECT 1 FROM Leads l2 WITH (NOLOCK) WHERE l2.Id = lp.LeadId AND l2.IsActive = 1)
    ) AS stuck;
END
GO

CREATE PROCEDURE usp_Reports_GetLeadTrend
    @OrganizationId UNIQUEIDENTIFIER,
    @Since DATETIME2 = NULL,
    @Until DATETIME2 = NULL,
    @BucketByMonth BIT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        CASE WHEN @BucketByMonth = 1 THEN DATEFROMPARTS(YEAR(CreatedAtUtc), MONTH(CreatedAtUtc), 1) ELSE CAST(CreatedAtUtc AS DATE) END AS BucketStart,
        COUNT(*) AS LeadCount
    FROM Leads WITH (NOLOCK)
    WHERE OrganizationId = @OrganizationId AND IsActive = 1 AND (@Since IS NULL OR CreatedAtUtc >= @Since)
      AND (@Until IS NULL OR CreatedAtUtc < @Until)
    GROUP BY CASE WHEN @BucketByMonth = 1 THEN DATEFROMPARTS(YEAR(CreatedAtUtc), MONTH(CreatedAtUtc), 1) ELSE CAST(CreatedAtUtc AS DATE) END
    ORDER BY BucketStart;
END
GO

CREATE PROCEDURE usp_Reports_GetLeadSourceBreakdown
    @OrganizationId UNIQUEIDENTIFIER,
