    VALUES (@Id, @OrganizationId, @Name, @Email, @Phone, @Company, @PipelineStageId, @Notes, @Source, @OwnerUserId, @IsActive, @CreatedByUserId, @CreatedAtUtc, @PipelineStageChangedAtUtc, @Latitude, @Longitude, @LocationCapturedAtUtc);
