-- ===== 044_sales_entries_product_status.sql =====
-- Extends usp_Leads_GetFieldSales (041_stored_procs_sales_entries.sql) so the Sales
-- Dashboard's product list shows each line item's current status, e.g.
-- "Consulting Hours (Active)" instead of just "Consulting Hours".
CREATE OR ALTER PROCEDURE usp_Leads_GetFieldSales
    @OrganizationId UNIQUEIDENTIFIER,
    @OwnerUserId NVARCHAR(100) = NULL,
    @Offset INT,
    @PageSize INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT COUNT(*)
    FROM Leads l WITH (NOLOCK)
    WHERE l.OrganizationId = @OrganizationId AND l.Source = 'FieldSales'
      AND (@OwnerUserId IS NULL OR l.OwnerUserId = @OwnerUserId);

    SELECT l.Id, l.Name, l.Email, l.Phone, l.Notes, l.OwnerUserId, l.CreatedAtUtc,
           l.Latitude, l.Longitude, l.LocationCapturedAtUtc,
           COALESCE(lp.TotalCost, 0) AS TotalCost,
           prod.Products
    FROM Leads l WITH (NOLOCK)
    LEFT JOIN (
        SELECT LeadId, SUM(Quantity * UnitPrice) AS TotalCost
        FROM LeadProducts WITH (NOLOCK)
        WHERE OrganizationId = @OrganizationId
        GROUP BY LeadId
    ) lp ON lp.LeadId = l.Id
    OUTER APPLY (
        SELECT STRING_AGG(p.Name + ' (' + ps.Name + ')', ', ') AS Products
        FROM LeadProducts lpx WITH (NOLOCK)
        JOIN Products p WITH (NOLOCK) ON p.Id = lpx.ProductId
        LEFT JOIN ProductStages ps WITH (NOLOCK) ON ps.Id = lpx.ProductStageId
        WHERE lpx.LeadId = l.Id
    ) prod
    WHERE l.OrganizationId = @OrganizationId AND l.Source = 'FieldSales'
      AND (@OwnerUserId IS NULL OR l.OwnerUserId = @OwnerUserId)
    ORDER BY l.CreatedAtUtc DESC
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END
GO


GO

-- ===== 045_sales_entries_location_range.sql =====
-- Backs the Sales Dashboard's admin-only coverage map/area view: every one of a
-- single rep's sales-entry locations within a date range, unpaged (unlike
-- usp_Leads_GetFieldSales, a single result set, no COUNT).
CREATE OR ALTER PROCEDURE usp_Leads_GetFieldSalesLocations
    @OrganizationId UNIQUEIDENTIFIER,
    @OwnerUserId NVARCHAR(100),
    @FromUtc DATETIME2,
    @ToUtc DATETIME2
AS
BEGIN
    SET NOCOUNT ON;

    SELECT l.Id, l.Name, l.Email, l.Phone, l.Notes, l.OwnerUserId, l.CreatedAtUtc,
           l.Latitude, l.Longitude, l.LocationCapturedAtUtc,
           COALESCE(lp.TotalCost, 0) AS TotalCost,
           prod.Products
    FROM Leads l WITH (NOLOCK)
    LEFT JOIN (
        SELECT LeadId, SUM(Quantity * UnitPrice) AS TotalCost
        FROM LeadProducts WITH (NOLOCK)
        WHERE OrganizationId = @OrganizationId
        GROUP BY LeadId
    ) lp ON lp.LeadId = l.Id
    OUTER APPLY (
        SELECT STRING_AGG(p.Name + ' (' + ps.Name + ')', ', ') AS Products
        FROM LeadProducts lpx WITH (NOLOCK)
        JOIN Products p WITH (NOLOCK) ON p.Id = lpx.ProductId
        LEFT JOIN ProductStages ps WITH (NOLOCK) ON ps.Id = lpx.ProductStageId
        WHERE lpx.LeadId = l.Id
    ) prod
    WHERE l.OrganizationId = @OrganizationId AND l.Source = 'FieldSales'
      AND l.OwnerUserId = @OwnerUserId
      AND l.Latitude IS NOT NULL AND l.Longitude IS NOT NULL
      AND l.CreatedAtUtc >= @FromUtc AND l.CreatedAtUtc < @ToUtc
    ORDER BY l.CreatedAtUtc ASC;
END
GO


GO

-- ===== 046_sales_by_rep.sql =====
-- Backs the Sales Dashboard's "Sales by rep" chart: org-wide per-rep entry
-- count + total value for FieldSales leads in a date range. Mirrors
-- usp_Reports_GetLeadsByOwnerRaw's ISNULL/GROUP BY/Since-Until shape
-- (036_stored_procs_dashboard_reports.sql) plus the LeadProducts value join
-- already used by usp_Leads_GetFieldSalesLocations.
CREATE OR ALTER PROCEDURE usp_Leads_GetFieldSalesByRep
    @OrganizationId UNIQUEIDENTIFIER,
    @Since DATETIME2 = NULL,
    @Until DATETIME2 = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT ISNULL(l.OwnerUserId, '') AS OwnerUserId,
           COUNT(*) AS EntryCount,
           COALESCE(SUM(lp.TotalCost), 0) AS TotalValue
    FROM Leads l WITH (NOLOCK)
    LEFT JOIN (
        SELECT LeadId, SUM(Quantity * UnitPrice) AS TotalCost
        FROM LeadProducts WITH (NOLOCK)
        WHERE OrganizationId = @OrganizationId
        GROUP BY LeadId
    ) lp ON lp.LeadId = l.Id
    WHERE l.OrganizationId = @OrganizationId AND l.Source = 'FieldSales'
      AND (@Since IS NULL OR l.CreatedAtUtc >= @Since)
      AND (@Until IS NULL OR l.CreatedAtUtc < @Until)
    GROUP BY l.OwnerUserId;
END
GO


GO

-- ===== 047_field_sales_company.sql =====
-- Extends usp_Leads_GetFieldSales (041_stored_procs_sales_entries.sql, last touched by
-- 044_sales_entries_product_status.sql) to also select Company -- it was added to the
-- Sales Entry form/Create endpoint without updating this read path, so a logged
-- Company never showed up on the rep's own entries list or the admin Sales Dashboard.
CREATE OR ALTER PROCEDURE usp_Leads_GetFieldSales
    @OrganizationId UNIQUEIDENTIFIER,
    @OwnerUserId NVARCHAR(100) = NULL,
    @Offset INT,
    @PageSize INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT COUNT(*)
    FROM Leads l WITH (NOLOCK)
    WHERE l.OrganizationId = @OrganizationId AND l.Source = 'FieldSales'
      AND (@OwnerUserId IS NULL OR l.OwnerUserId = @OwnerUserId);

    SELECT l.Id, l.Name, l.Company, l.Email, l.Phone, l.Notes, l.OwnerUserId, l.CreatedAtUtc,
           l.Latitude, l.Longitude, l.LocationCapturedAtUtc,
           COALESCE(lp.TotalCost, 0) AS TotalCost,
           prod.Products
    FROM Leads l WITH (NOLOCK)
    LEFT JOIN (
        SELECT LeadId, SUM(Quantity * UnitPrice) AS TotalCost
        FROM LeadProducts WITH (NOLOCK)
        WHERE OrganizationId = @OrganizationId
        GROUP BY LeadId
    ) lp ON lp.LeadId = l.Id
    OUTER APPLY (
        SELECT STRING_AGG(p.Name + ' (' + ps.Name + ')', ', ') AS Products
        FROM LeadProducts lpx WITH (NOLOCK)
        JOIN Products p WITH (NOLOCK) ON p.Id = lpx.ProductId
        LEFT JOIN ProductStages ps WITH (NOLOCK) ON ps.Id = lpx.ProductStageId
        WHERE lpx.LeadId = l.Id
    ) prod
    WHERE l.OrganizationId = @OrganizationId AND l.Source = 'FieldSales'
      AND (@OwnerUserId IS NULL OR l.OwnerUserId = @OwnerUserId)
    ORDER BY l.CreatedAtUtc DESC
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END
GO


GO

-- ===== 048_leads_count_active.sql =====
-- Backs the plan's record-limit check (LeadsController.Create, SalesEntriesController.Create)
-- and the usage-warning banner. IsActive = 1 excludes soft-deleted Leads, matching how a
-- customer would count "my current leads" -- a deleted Lead shouldn't count against their limit.
CREATE OR ALTER PROCEDURE usp_Leads_CountActive
    @OrganizationId UNIQUEIDENTIFIER
AS
BEGIN
    SET NOCOUNT ON;
    SELECT COUNT(*) FROM Leads WITH (NOLOCK) WHERE OrganizationId = @OrganizationId AND IsActive = 1;
END
GO


GO

